import { createClient } from "@supabase/supabase-js";
import { POST as baseChatPost } from "../chat/route";
import { recordRelationshipChatTurn } from "../../../lib/relationship-time";
import { operationClient, progressOperation, type LegacyOperation } from '../../../lib/legacy-drain';

const SUPABASE_URL = "https://tzozajnwznxqgxnjikoy.supabase.co";
const SUPABASE_PUBLISHABLE_KEY =
  "sb_publishable_ZEYZ3tc1RLE7EuClbUP4vA_ISHWfKr1";
const MAX_MEMORY = 30;
const HISTORY_DIAGNOSTIC_PREFIX = "履歴診断:";

function createAuthenticatedSupabase(accessToken: string) {
  return createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
    global: { headers: { Authorization: `Bearer ${accessToken}` } },
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false,
    },
  });
}

function sanitizeMemory(value: unknown): string[] {
  return Array.isArray(value)
    ? value
        .filter((item): item is string => typeof item === "string")
        .map((item) => item.trim())
        .filter(Boolean)
        .slice(-MAX_MEMORY)
    : [];
}

function isMemoryRecallQuestion(message: unknown) {
  if (typeof message !== "string") return false;
  const normalized = message.replace(/\s+/g, "");
  return [
    "覚えてる",
    "覚えている",
    "覚えてた",
    "何覚えてる",
    "なに覚えてる",
    "何を覚えてる",
    "なにを覚えてる",
    "記憶してる",
    "記憶している",
    "私のこと覚えて",
    "俺のこと覚えて",
    "僕のこと覚えて",
    "好み覚えて",
    "何知ってる",
    "なに知ってる",
  ].some((pattern) => normalized.includes(pattern));
}

function isDiagnosticHistoryItem(item: any) {
  return (
    typeof item?.text === "string" &&
    (item.text.startsWith(HISTORY_DIAGNOSTIC_PREFIX) ||
      item.text.startsWith("診断結果：history="))
  );
}

function createRecallAwareMessage(
  message: unknown,
  history: unknown,
  recallMode: boolean
) {
  if (!recallMode || typeof message !== "string") return message;

  const recentConversation = Array.isArray(history)
    ? history
        .filter(
          (item: any) =>
            item &&
            (item.role === "user" || item.role === "misaki") &&
            typeof item.text === "string" &&
            !isDiagnosticHistoryItem(item)
        )
        .slice(-20)
        .map(
          (item: any) =>
            `${item.role === "user" ? "ユーザー" : "美咲"}: ${item.text}`
        )
        .join("\n")
    : "";

  return `${message}\n\n【記憶確認の回答根拠】\n以下は、この質問より前に実際に交わした直近の会話です。これは参考例ではなく事実の会話履歴です。\n質問された話題と関係する発言がこの中にある場合、その具体的内容を使って自然に答えてください。\n履歴から具体的内容を答えられる場合、それは美咲が思い出せている状態です。「覚えていない」「思い出せない」「まだ何も思い出せていない」「ヒントをちょうだい」など、回答内容と矛盾する表現を絶対に続けないでください。\n過去の美咲の発言に「覚えていない」「思い出せない」があっても、今回の履歴に根拠が見つかったなら、その古い誤答を引き継がず、今は思い出せたものとして自然に答えてください。\n履歴にも長期記憶にも根拠がない場合だけ、知らないことを作らずに答えてください。\n\n${recentConversation || "直近の会話履歴なし"}`;
}

function createForwardedRequest(request: Request, body: unknown) {
  return new Request(request.url, {
    method: "POST",
    headers: request.headers,
    body: JSON.stringify(body),
  });
}

async function callBaseChat(request: Request, body: unknown) {
  // base route 自身が Gemini の意味的再試行を一回の usage 消費内で処理する。
  // proxy から base route を再度呼ぶと新しい usage request id が発行されるため、
  // ここでは一つのブラウザ送信につき base route は一度だけ呼ぶ。
  return baseChatPost(createForwardedRequest(request, body));
}

export async function POST(request: Request) {
  let operation: LegacyOperation | null = null;
  try {
    const body = await request.json();
    const authorization = request.headers.get("authorization") ?? "";

    if (!authorization.startsWith("Bearer ")) {
      return Response.json(
        { error: "ログイン情報を確認できませんでした。ページを再読み込みしてね。" },
        { status: 401 }
      );
    }

    const accessToken = authorization.slice("Bearer ".length).trim();
    let supabase = createAuthenticatedSupabase(accessToken);
    const { data: userData, error: userError } =
      await supabase.auth.getUser(accessToken);

    if (userError || !userData.user) {
      return Response.json(
        { error: "ログイン情報を確認できませんでした。ページを再読み込みしてね。" },
        { status: 401 }
      );
    }

    const isAnonymous = userData.user.is_anonymous === true;
    const recallMode = isMemoryRecallQuestion(body?.message);
    const messageForModel = createRecallAwareMessage(
      body?.message,
      body?.history,
      recallMode
    );

    // 匿名利用ではSupabaseを会話・記憶・関係時間の保存先にしない。
    // ブラウザから届いた一時記憶と直近の会話履歴を、そのブラウザセッション中の回答に使う。
    if (isAnonymous) {
      const temporaryMemory = sanitizeMemory(body?.memory);
      const safeBody = {
        ...body,
        message: messageForModel,
        memory: temporaryMemory,
      };

      const baseResponse = await callBaseChat(request, safeBody);
      if (!baseResponse.ok) return baseResponse;

      const result = await baseResponse.json();
      const returnedMemory = sanitizeMemory(result?.memory);

      return Response.json({
        ...result,
        memory: recallMode ? temporaryMemory : returnedMemory,
        memorySynced: false,
        relationshipTimeSynced: false,
        ephemeral: true,
      });
    }

    // 保存済みアカウントではSupabaseのmemoryを唯一の正本として使う。
    // 記憶確認の質問でも、正本memoryに加えてブラウザから届く直近の会話履歴を文脈として残す。
    const { data: state, error: stateError } = await supabase
      .from("misaki_user_conversation_state")
      .select("memory")
      .eq("user_id", userData.user.id)
      .maybeSingle();

    if (stateError) {
      console.error("CANONICAL MEMORY READ ERROR:", stateError);
      return Response.json(
        { error: "美咲の記憶を確認できませんでした。少ししてからもう一度話しかけてね。" },
        { status: 500 }
      );
    }

    const canonicalMemory = sanitizeMemory(state?.memory);
    const safeBody = {
      ...body,
      message: messageForModel,
      memory: canonicalMemory,
    };

    const userMessageAt = new Date();
    const baseResponse = await callBaseChat(request, safeBody);
    if (!baseResponse.ok) return baseResponse;

    const result = await baseResponse.json();
    const misakiMessageAt = new Date();
    operation = result.maintenanceOperation;
    if (!operation) throw new Error('operation missing');
    supabase = operationClient(accessToken, operation);
    const returnedMemory = sanitizeMemory(result?.memory);
    const nextMemory = recallMode ? canonicalMemory : returnedMemory;
    const historyForSync =
      typeof body?.message === "string" && typeof result?.reply === "string"
        ? [
            { role: "user", text: body.message },
            { role: "misaki", text: result.reply },
          ]
        : [];

    const { error: syncError } = await (supabase.rpc as any)(
      "sync_user_conversation_state",
      { p_history: historyForSync, p_memory: nextMemory }
    );

    if (syncError) {
      await progressOperation(operation, 'unknown');
      console.error("CANONICAL MEMORY WRITE ERROR:", syncError);
      return Response.json(
        { error: "美咲の記憶を保存できませんでした。もう一度話しかけてね。" },
        { status: 500 }
      );
    }

    // 会話と記憶の保存が成功した後にだけ関係時間を進める。
    // 関係時間の記録失敗で、すでに生成できた会話そのものは失敗扱いにしない。
    const relationshipTimeSynced = await recordRelationshipChatTurn(
      supabase,
      false,
      userMessageAt,
      misakiMessageAt
    );

    return Response.json({
      ...result,
      memory: nextMemory,
      memorySynced: true,
      relationshipTimeSynced,
    });
  } catch (error) {
    if (operation) await progressOperation(operation, 'unknown');
    console.error("CHAT PROXY ERROR:", error);
    return Response.json(
      { error: "今ちょっと美咲とつながりにくいみたい。少ししてからもう一度話しかけてね。" },
      { status: 500 }
    );
  }
}

