 import { selectMisakiProactivePhoto } from "./proactive-photo.ts";
@@ -12,6 +13,6 @@ function safeHistory(v:unknown):ChatMessage[]{return Array.isArray(v)?v.filter(x
 function safeMemory(v:unknown):string[]{return Array.isArray(v)?v.filter(x=>typeof x==="string"&&x.trim()).map(x=>x.trim()).slice(-30):[]}
 function extractJsonObject(t:string){const s=t.trim();try{return JSON.parse(s)}catch{const a=s.indexOf("{"),b=s.lastIndexOf("}");if(a>=0&&b>a)return JSON.parse(s.slice(a,b+1));throw new Error("Gemini returned invalid JSON")}}
 async function generateMessage(key:string,persona:string,history:ChatMessage[],memory:string[],decision:ProactiveDecisionContext,currentTime:string){const recent=history.slice(-20).map(m=>`${m.role==="user"?"ユーザー":"美咲"}: ${m.text}`).join("
"),life={situation:decision.situation,plan:decision.plan,evidence:decision.lifeEvidence,confidence:decision.lifeConfidence};const prompt=`${persona}

${createProactiveDecisionGuide(decision)}

${createProactiveLifeGuide(life)}

【美咲の体内時計からの自発メッセージ】
これはユーザーへの返答ではなく、美咲から自然に送る短いLINEです。
現在時刻（日本時間）: ${currentTime}
関係性ポイント: ${decision.relationshipPoints}
長期記憶:
${memory.length?memory.map(x=>`・${x}`).join("
"):"なし"}
最近の会話:
${recent||"なし"}

ルール:
・1〜2文を基本にする
・毎回質問で終わらせない
・ユーザーの現在地、勤務中、休み、体調、予定などは生活文脈の明示的根拠がある範囲だけ使う
・古い予定を現在進行形だと断定しない
・過去の出来事を会話や記憶にないのに作らない
・AI、システム、通知、体内時計、タグ名、内部状態を出さない
