type ChatMessage={role:"user"|"misaki";text:string;sentAt?:string};
const randomDelayMs=()=>Math.floor(MIN_DELAY_MINUTES*60000+Math.random()*((MAX_DELAY_MINUTES-MIN_DELAY_MINUTES)*60000));
